import {deck,points} from './engine.mjs';
export const handPoints=h=>points(h.cards)+(h.adjust??0);
export const dealerPoints=g=>Math.max(0,points(g.dealer)+(g.dealerAdjust??0));
export const hasBlackjackActed=p=>!!p.acted||(p.hands??[]).some(h=>h.cards.length>2||h.fromSplit||h.doubled||(h.done&&handPoints(h)!==21));
const money=n=>Math.round(n*100)/100;
const check=(ok,message)=>{if(!ok)throw Error(message)};
const value=c=>c.r===14?11:Math.min(c.r,10);
const hand=(cards=[],bet=0,extra={})=>({cards,bet,done:false,result:'',delta:0,...extra});
function normalize(g){for(const p of g.players){p.hands??=[hand(p.hand,p.bet,{done:p.done,doubled:p.doubled})];p.active??=0;p.hand=p.hands[p.active]?.cards??[];p.bet=p.hands.reduce((n,h)=>n+h.bet,0);p.done=!!p.departed||p.hands.every(h=>h.done)}}
export function newBlackjack(banks,random=Math.random,now=Date.now()){const shoe=Array.from({length:6},()=>deck(random)).flat();for(let i=shoe.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[shoe[i],shoe[j]]=[shoe[j],shoe[i]]}return{deck:shoe,players:banks.map(bank=>({bank,hands:[hand()],active:0,hand:[],bet:0,done:false,result:'',delta:0})),dealer:[],phase:'bets',turn:-1,reveal:false,done:false,dealt:0,nextAt:now+1000,deadline:now+30000}}
export function canSplit(p){const h=p.hands[p.active];return h.cards.length===2&&!h.splitAces&&value(h.cards[0])===value(h.cards[1])&&p.hands.length<4&&p.bank>=h.bet*(p.bounty?2:1)}
function next(g,now){normalize(g);g.turn=g.players.findIndex(p=>!p.done);if(g.turn<0){g.phase='dealer';g.reveal=true;g.nextAt=now+1800}else{const p=g.players[g.turn];p.active=p.hands.findIndex(h=>!h.done);normalize(g);g.phase='players';g.nextAt=now+1100;g.deadline=now+45000}}
function finish(g){const d=dealerPoints(g),dn=!g.dealerModified&&g.dealer.length===2&&d===21;for(const p of g.players){for(const h of p.hands){const n=handPoints(h),natural=!h.modified&&!h.fromSplit&&h.cards.length===2&&n===21&&!h.doubled;let back=0;h.result='负';if(n>21)h.result='爆牌';else if(dn){if(natural){back=h.bet;h.result='平局'}}else if(natural){back=h.bet*2.5;h.result='BLACKJACK'}else if(d>21||n>d){back=h.bet*2;h.result='胜'}else if(n===d){back=h.bet;h.result='平局'}if(p.bounty&&h.bet){const won=back>h.bet,lost=back<h.bet;const multiplier=won?(natural?2.5:1.5):lost?-(n>21?2:1.5):0;back=h.bet+h.bet*multiplier}p.bank=money(p.bank+back);h.delta=money(back-h.bet);h.done=true}p.bank=money(p.bank+(p.riskReserve??0));p.riskReserve=0;p.delta=money(p.hands.reduce((n,h)=>n+h.delta,0)-(p.skillCost??0));p.result=p.hands.map((h,i)=>(p.hands.length>1?'第 '+(i+1)+' 手 ':'')+h.result).join(' / ')}normalize(g);g.done=true;g.phase='done';g.turn=-1}
export function blackjackAct(g,i,action,amount,now=Date.now()){normalize(g);const p=g.players[i];check(p&&!g.done,'本局已结束');if(g.phase==='bets'){check(action==='bet'&&!p.bet,'请等待其他玩家下注');check(Number.isSafeInteger(amount)&&amount>0&&amount*(p.bounty?2:1)<=p.bank,'请输入不超过可用筹码的正整数');p.hands[0].bet=amount;p.bank-=amount*(p.bounty?2:1);p.riskReserve=(p.riskReserve??0)+(p.bounty?amount:0);normalize(g);return}
 check(g.phase==='players'&&g.turn===i&&!p.done,'请等待发牌完成或轮到你');const h=p.hands[p.active];
 if(action==='split'){check(canSplit(p),'需要同点数的两张牌、足够筹码，最多分成四手');p.bank-=h.bet*(p.bounty?2:1);p.riskReserve=(p.riskReserve??0)+(p.bounty?h.bet:0);const ace=h.cards[0].r===14;const other=hand([h.cards.pop()],h.bet,{fromSplit:true,splitAces:ace});h.fromSplit=true;h.splitAces=ace;p.hands.splice(p.active+1,0,other);g.queue=[{seat:i,index:p.active},{seat:i,index:p.active+1}];g.phase='splitDeal';g.nextAt=now+1000}
 else if(action==='stand'){h.done=true;next(g,now)}
 else if(action==='hit'||action==='double'){if(action==='double'){check(h.cards.length===2&&!h.splitAces&&p.bank>=h.bet*(p.bounty?2:1),'当前不能加倍');p.bank-=h.bet*(p.bounty?2:1);p.riskReserve=(p.riskReserve??0)+(p.bounty?h.bet:0);h.bet*=2;h.doubled=true}h.cards.push(g.deck.pop());if(action==='double'||handPoints(h)>=21)h.done=true;g.phase='draw';g.nextAt=now+1200}
 else throw Error('未知操作');p.acted=true;normalize(g)
}
export function blackjackTick(g,bots,now=Date.now()){normalize(g);if(g.done||now<g.nextAt)return false;
 if(g.phase==='bets'){let changed=false;g.players.forEach((p,i)=>{if(!p.departed&&!p.bet&&(bots[i]||now>=g.deadline)){const n=Math.min(50,Math.floor(p.bank/(p.bounty?2:1)));p.bank-=n*(p.bounty?2:1);p.riskReserve=(p.riskReserve??0)+(p.bounty?n:0);p.hands[0].bet=n;changed=true}});normalize(g);if(g.players.every(p=>p.departed||p.bet>0)){g.phase='deal';g.nextAt=now+600;changed=true}return changed}
 if(g.phase==='deal'){const slot=g.dealt%(g.players.length+1);if(slot===g.players.length)g.dealer.push(g.deck.pop());else g.players[slot].hands[0].cards.push(g.deck.pop());g.dealt++;g.nextAt=now+1100;if(g.dealt===2*(g.players.length+1)){g.players.forEach(p=>p.hands[0].done=points(p.hands[0].cards)===21);if(points(g.dealer)===21){g.reveal=true;g.phase='dealer';g.nextAt=now+1800}else next(g,now)}normalize(g);return true}
 if(g.phase==='splitDeal'){const q=g.queue.shift(),h=g.players[q.seat].hands[q.index];h.cards.push(g.deck.pop());h.done=h.splitAces||handPoints(h)>=21;g.nextAt=now+1100;if(!g.queue.length){g.phase='draw';g.nextAt=now+1200}normalize(g);return true}
 if(g.phase==='draw'){next(g,now);return true}
 if(g.phase==='players'&&g.players[g.turn]?.departed){next(g,now);return true}
 if(g.phase==='players'&&(bots[g.turn]||now>=g.deadline)){const p=g.players[g.turn],h=p.hands[p.active],n=handPoints(h),up=value(g.dealer[0]);let a='stand';if(bots[g.turn]){if(canSplit(p)&&[8,11].includes(value(h.cards[0])))a='split';else if(h.cards.length===2&&p.bank>=h.bet*(p.bounty?2:1)&&[10,11].includes(n)&&up<10)a='double';else if(n<12||n<17&&up>=7||n===12&&up<4)a='hit'}blackjackAct(g,g.turn,a,null,now);return true}
 if(g.phase==='dealer'){if(dealerPoints(g)<17&&g.players.some(p=>p.hands.some(h=>handPoints(h)<=21))){g.dealer.push(g.deck.pop());g.nextAt=now+1700}else finish(g);return true}return false
}
export function blackjackView(g){normalize(g);return{players:g.players.map(p=>({hand:p.hand,bet:p.bet,done:p.done,result:p.result,delta:p.delta,bank:p.bank,bounty:!!p.bounty,acted:hasBlackjackActed(p),riskReserve:p.riskReserve??0,active:p.active,canSplit:canSplit(p),hands:p.hands.map(h=>({...h,points:handPoints(h)}))})),dealer:g.dealer.map((c,n)=>n===1&&!g.reveal?null:c),dealerPoints:Math.max(0,points(g.dealer.filter((c,n)=>n!==1||g.reveal))+(g.dealerAdjust??0)),phase:g.phase,turn:g.turn,reveal:g.reveal,done:g.done}}
